/**
 * Sentinel core function tests
 *
 * Runs the heuristic functions from src/sentinel-core.ts against real
 * session fixture data to verify loop detection works.
 *
 * Usage: npm test          (in the sentinel/ directory)
 *        npm run test:watch (watch mode)
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it, expect } from "vitest";
import {
  extractThinkingBlocks,
  countConsecutiveAssistant,
  extractToolCalls,
  calcHeuristicScore,
  analyzeThinkingRepetition,
  countSelfQuestions,
  ngramJaccard,
  sumInputTokens,
  avgCacheRatio,
  analyzeToolCallRepetition,
} from "../src/sentinel-core";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const FIXTURES_DIR = path.join(__dirname, "fixtures");

function loadFixture(name: string): unknown[] {
  const raw = fs.readFileSync(path.join(FIXTURES_DIR, name), "utf8");
  return JSON.parse(raw) as unknown[];
}

// =============================================================================
// Fixtures
// =============================================================================

describe("loop session fixture", () => {
  const entries = loadFixture("loop-session.json");

  it("has session data", () => {
    expect(entries.length).toBeGreaterThan(0);
  });

  it("extracts thinking blocks", () => {
    const blocks = extractThinkingBlocks(entries);
    expect(blocks.length).toBeGreaterThan(0);
  });

  it("extracts tool calls", () => {
    const calls = extractToolCalls(entries);
    expect(calls.length).toBeGreaterThan(0);
  });

  it("counts consecutive assistant messages", () => {
    const count = countConsecutiveAssistant(entries);
    expect(count).toBeGreaterThan(1);
  });

  it("scores above the auto-abort threshold", () => {
    const blocks = extractThinkingBlocks(entries);
    const ca = countConsecutiveAssistant(entries);
    const calls = extractToolCalls(entries);
    const breakdown = calcHeuristicScore(blocks, ca, calls, entries);
    expect(breakdown.total).toBeGreaterThan(0.55);
  });

  it("scores above the sentinel trigger threshold", () => {
    const blocks = extractThinkingBlocks(entries);
    const ca = countConsecutiveAssistant(entries);
    const calls = extractToolCalls(entries);
    const breakdown = calcHeuristicScore(blocks, ca, calls, entries);
    expect(breakdown.total).toBeGreaterThan(0.15);
  });

  it("shows score progression — crosses sentinel threshold eventually", () => {
    // Simulate running the check as the session grows
    let crossedSentinel = false;
    let crossedAbort = false;
    for (let i = 10; i <= entries.length; i += 10) {
      const slice = entries.slice(0, i);
      const blocks = extractThinkingBlocks(slice);
      const ca = countConsecutiveAssistant(slice);
      const calls = extractToolCalls(slice);
      const score = calcHeuristicScore(blocks, ca, calls, slice).total;
      if (score >= 0.15) crossedSentinel = true;
      if (score >= 0.55) crossedAbort = true;
    }
    expect(crossedSentinel).toBe(true);
    expect(crossedAbort).toBe(true);
  });
});

describe("normal session fixture", () => {
  const entries = loadFixture("normal-session.json");

  it("has session data", () => {
    expect(entries.length).toBeGreaterThan(0);
  });

  it("scores below the auto-abort threshold", () => {
    const blocks = extractThinkingBlocks(entries);
    const ca = countConsecutiveAssistant(entries);
    const calls = extractToolCalls(entries);
    const breakdown = calcHeuristicScore(blocks, ca, calls, entries);
    expect(breakdown.total).toBeLessThan(0.55);
  });
});

// =============================================================================
// Unit: ngramJaccard
// =============================================================================

describe("ngramJaccard", () => {
  it("returns 1 for identical strings", () => {
    expect(ngramJaccard("hello world foo", "hello world foo")).toBe(1);
  });

  it("returns 0 for completely different strings", () => {
    const sim = ngramJaccard("aaa bbb ccc", "xxx yyy zzz");
    expect(sim).toBe(0);
  });

  it("returns partial similarity for overlapping strings", () => {
    const sim = ngramJaccard("hello world foo bar baz", "world foo bar baz qux");
    expect(sim).toBeGreaterThan(0);
    expect(sim).toBeLessThan(1);
  });

  it("returns 0 when strings are shorter than n-gram size", () => {
    expect(ngramJaccard("a b", "x y", 3)).toBe(0);
  });
});

// =============================================================================
// Unit: analyzeThinkingRepetition
// =============================================================================

describe("analyzeThinkingRepetition", () => {
  it("returns 0 for a single block", () => {
    expect(analyzeThinkingRepetition(["just one block"])).toBe(0);
  });

  it("returns 0 for an empty array", () => {
    expect(analyzeThinkingRepetition([])).toBe(0);
  });

  it("returns high score for identical blocks", () => {
    const repeated = Array(4).fill("the same thinking over and over again");
    expect(analyzeThinkingRepetition(repeated)).toBeGreaterThan(0.5);
  });

  it("returns low score for diverse blocks", () => {
    const diverse = [
      "first I need to check the config file",
      "now let me look at the database schema",
      "running the build to see if it compiles",
      "deploying to staging for testing",
    ];
    expect(analyzeThinkingRepetition(diverse)).toBeLessThan(0.3);
  });
});

// =============================================================================
// Unit: countSelfQuestions
// =============================================================================

describe("countSelfQuestions", () => {
  it("counts blocks ending with a question", () => {
    const blocks = [
      "Let me think about this.\nWhat should I do next?",
      "I will try the first approach.",
      "Hmm, maybe I should look at the docs?\nActually no.",
      "Let me check if this works?",
    ];
    expect(countSelfQuestions(blocks)).toBe(2);
  });

  it("ignores short question-like endings", () => {
    const blocks = ["ok?"];
    expect(countSelfQuestions(blocks)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(countSelfQuestions([])).toBe(0);
  });
});

// =============================================================================
// Unit: analyzeToolCallRepetition
// =============================================================================

describe("analyzeToolCallRepetition", () => {
  it("returns 0 for fewer than 3 file ops", () => {
    expect(
      analyzeToolCallRepetition([
        { tool: "read", args: '{"path":"/foo"}' },
        { tool: "bash", args: "ls" },
      ]),
    ).toBe(0);
  });

  it("detects repeated reads of the same file", () => {
    const calls = Array(5).fill({ tool: "read", args: '{"path":"/etc/config.toml"}' });
    expect(analyzeToolCallRepetition(calls)).toBeGreaterThan(0);
  });
});

// =============================================================================
// Unit: sumInputTokens / avgCacheRatio
// =============================================================================

describe("sumInputTokens", () => {
  it("returns 0 for empty entries", () => {
    expect(sumInputTokens([])).toBe(0);
  });

  it("sums input tokens from assistant messages", () => {
    const entries = [
      { type: "message", message: { role: "assistant", usage: { input: 100 } } },
      { type: "message", message: { role: "user" } },
      { type: "message", message: { role: "assistant", usage: { input: 200 } } },
    ];
    expect(sumInputTokens(entries)).toBe(300);
  });
});

describe("avgCacheRatio", () => {
  it("returns 1 when there are no input tokens", () => {
    expect(avgCacheRatio([])).toBe(1);
  });

  it("calculates cache ratio correctly", () => {
    const entries = [
      { type: "message", message: { role: "assistant", usage: { input: 100, cacheRead: 100 } } },
    ];
    expect(avgCacheRatio(entries)).toBe(0.5);
  });
});

/**
 * Sentinel Core — Pure Heuristic Analysis
 *
 * All the loop-detection logic, extracted into importable functions
 * so the same code can be tested against real session data.
 */

// =============================================================================
// Types
// =============================================================================

export interface ToolCall {
  tool: string;
  args: string;
}

export interface HeuristicBreakdown {
  thinkingRepetition: number;
  turnPressure: number;
  tokenVolume: number;
  selfQuestioning: number;
  toolCallRepetition: number;
  total: number;
}

// =============================================================================
// Session Extraction
// =============================================================================

/** Extract thinking blocks from session entries */
export function extractThinkingBlocks(entries: unknown[]): string[] {
  const blocks: string[] = [];
  for (const entry of entries as Array<{
    type?: string;
    message?: { role?: string; content?: Array<{ type?: string; thinking?: string }> };
  }>) {
    if (entry.type === "message" && entry.message?.role === "assistant") {
      for (const item of entry.message.content ?? []) {
        if (item.type === "thinking" && item.thinking) {
          blocks.push(item.thinking);
        }
      }
    }
  }
  return blocks;
}

/** Count consecutive assistant messages since last user message */
export function countConsecutiveAssistant(entries: unknown[]): number {
  let count = 0;
  for (let i = (entries as unknown[]).length - 1; i >= 0; i--) {
    const entry = entries[i] as { type?: string; message?: { role?: string } };
    if (entry.type === "message") {
      if (entry.message?.role === "assistant") {
        count++;
      } else if (entry.message?.role === "user") {
        break;
      }
    }
  }
  return count;
}

/** Extract tool calls from session entries */
export function extractToolCalls(entries: unknown[]): ToolCall[] {
  const calls: ToolCall[] = [];
  for (const entry of entries as Array<{
    type?: string;
    message?: { role?: string; content?: Array<Record<string, unknown>> };
  }>) {
    if (entry.type === "message" && entry.message?.role === "assistant") {
      for (const item of entry.message.content ?? []) {
        if (!item || typeof item !== "object") continue;
        const type = item.type;
        if (type === "tool_use") {
          calls.push({
            tool: (item.name as string) ?? "",
            args: typeof item.arguments === "string"
              ? item.arguments
              : JSON.stringify(item.arguments ?? {}),
          });
        } else if (type === "toolCall") {
          // Kilo/pi stores tool call name at top level of the item
          calls.push({
            tool: (item.name as string) ?? "",
            args: JSON.stringify(item.arguments ?? {}),
          });
        }
      }
    }
  }
  return calls;
}

/** Sum total input tokens across all assistant messages */
export function sumInputTokens(entries: unknown[]): number {
  let total = 0;
  for (const entry of entries as Array<{
    type?: string;
    message?: { role?: string; usage?: { input?: number } };
  }>) {
    if (entry.type === "message" && entry.message?.role === "assistant") {
      total += entry.message.usage?.input ?? 0;
    }
  }
  return total;
}

/** Average cache hit ratio across assistant messages (0–1) */
export function avgCacheRatio(entries: unknown[]): number {
  let totalInput = 0;
  let totalCache = 0;
  for (const entry of entries as Array<{
    type?: string;
    message?: { role?: string; usage?: { input?: number; cacheRead?: number } };
  }>) {
    if (entry.type === "message" && entry.message?.role === "assistant") {
      const usage = entry.message.usage;
      if (usage) {
        totalInput += usage.input ?? 0;
        totalCache += usage.cacheRead ?? 0;
      }
    }
  }
  if (totalInput === 0) return 1;
  return totalCache / (totalCache + totalInput);
}

// =============================================================================
// Similarity
// =============================================================================

/** Jaccard similarity of word n-grams between two strings */
export function ngramJaccard(a: string, b: string, n: number = 3): number {
  const aWords = a.toLowerCase().split(/\s+/);
  const bWords = b.toLowerCase().split(/\s+/);
  const aNgrams = new Set<string>();
  const bNgrams = new Set<string>();

  for (let i = 0; i <= aWords.length - n; i++) {
    aNgrams.add(aWords.slice(i, i + n).join(" "));
  }
  for (let i = 0; i <= bWords.length - n; i++) {
    bNgrams.add(bWords.slice(i, i + n).join(" "));
  }

  if (aNgrams.size === 0 || bNgrams.size === 0) return 0;

  let intersection = 0;
  for (const ng of aNgrams) {
    if (bNgrams.has(ng)) intersection++;
  }

  const union = aNgrams.size + bNgrams.size - intersection;
  return intersection / union;
}

// =============================================================================
// Heuristic Signals
// =============================================================================

/** Analyze thinking repetition across consecutive blocks */
export function analyzeThinkingRepetition(blocks: string[]): number {
  if (blocks.length < 2) return 0;

  let maxOverlap = 0;
  let highOverlapStreak = 0;

  for (let i = 1; i < blocks.length; i++) {
    const overlap = ngramJaccard(blocks[i - 1], blocks[i]);
    maxOverlap = Math.max(maxOverlap, overlap);
    if (overlap > 0.45) {
      highOverlapStreak++;
    } else {
      highOverlapStreak = 0;
    }
  }

  const streakBonus = Math.min(highOverlapStreak / 3, 1) * 0.3;
  return Math.min(maxOverlap * 0.7 + streakBonus, 1);
}

/** Count thinking blocks that end with a self-directed question */
export function countSelfQuestions(blocks: string[]): number {
  let count = 0;
  for (const block of blocks) {
    const lines = block.split("\n").filter((l) => l.trim());
    const lastLine = lines[lines.length - 1]?.trim() ?? "";
    if (lastLine.endsWith("?") && lastLine.length > 10) {
      count++;
    }
  }
  return count;
}

/** Detect repeated tool calls (same tool + similar args) */
export function analyzeToolCallRepetition(calls: ToolCall[]): number {
  if (calls.length < 3) return 0;

  const fileOps = calls.filter((c) => c.tool === "read" || c.tool === "bash");
  if (fileOps.length < 3) return 0;

  const filePaths = fileOps.map((c) => {
    const match = c.args.match(/(?:path|file|command)["\s]*[:=\s]*["']?([\/\w.-]+[\w.-]+)/i);
    return match?.[1] ?? c.args.slice(0, 80);
  });

  const pathCounts = new Map<string, number>();
  for (const p of filePaths) {
    pathCounts.set(p, (pathCounts.get(p) ?? 0) + 1);
  }

  const maxRepeats = Math.max(...pathCounts.values(), 0);
  if (maxRepeats >= 3) {
    return Math.min(maxRepeats / 5, 1);
  }
  return 0;
}

// =============================================================================
// Overall Score
// =============================================================================

/** Compute overall heuristic loop score (0–1) with full breakdown */
export function calcHeuristicScore(
  thinkingBlocks: string[],
  consecutiveAssistant: number,
  toolCalls: ToolCall[],
  entries: unknown[],
): HeuristicBreakdown {
  const repetition = analyzeThinkingRepetition(thinkingBlocks);
  const turnPressure = Math.min(consecutiveAssistant / 12, 1);
  const questionRatio = countSelfQuestions(thinkingBlocks) / Math.max(thinkingBlocks.length, 1);
  const toolRep = analyzeToolCallRepetition(toolCalls);

  // Token volume: normal sessions use ~5K–50K input tokens total.
  // The loop session used 1.5M. Score rises sharply above 200K.
  const totalInputTokens = sumInputTokens(entries);
  const tokenScore = Math.min(Math.max((totalInputTokens - 200_000) / 300_000, 0), 1);

  const total = Math.min(
    repetition * 0.25 +
    turnPressure * 0.30 +
    tokenScore * 0.25 +
    questionRatio * 0.10 +
    toolRep * 0.10,
    1,
  );

  return {
    thinkingRepetition: repetition * 0.25,
    turnPressure: turnPressure * 0.30,
    tokenVolume: tokenScore * 0.25,
    selfQuestioning: questionRatio * 0.10,
    toolCallRepetition: toolRep * 0.10,
    total,
  };
}

